  flex: 0 0 auto;
  font-size: 12px;
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
  white-space: nowrap;
}

.job-progress-panel__empty {
  flex: 1 1 auto;
  min-height: 0;
  padding: 20px 16px;
  overflow-y: auto;
}

.job-progress-panel__empty-title {
  margin: 0 0 4px;
  font-size: 13px;
  font-weight: 500;
}

.job-progress-panel__empty-hint {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
  overflow-wrap: anywhere;
}

.job-progress-panel__list {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  min-height: 0;
  margin: 0;
  padding: 10px;
  overflow-y: auto;
  list-style: none;
}

.job-progress-panel__item {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--card);
  color: var(--foreground);
}

.job-progress-panel__item-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.job-progress-panel__job-title {
  min-width: 0;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.job-progress-panel__badge {
  flex: 0 0 auto;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--muted);
  font-size: 11px;
  line-height: 1.6;
  white-space: nowrap;
}

.job-progress-panel__item[data-status="running"] .job-progress-panel__badge {
  background: color-mix(in srgb, var(--job-progress-running) 16%, transparent);
  color: var(--job-progress-running);
}

.job-progress-panel__item[data-status="completed"] .job-progress-panel__badge {
  background: color-mix(in srgb, var(--job-progress-success) 16%, transparent);
  color: var(--job-progress-success);
}

.job-progress-panel__item[data-status="failed"] .job-progress-panel__badge {
  background: color-mix(in srgb, var(--job-progress-danger) 16%, transparent);
  color: var(--job-progress-danger);
}

.job-progress-panel__item[data-status="cancelled"] .job-progress-panel__badge {
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
}

.job-progress-panel__bar {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  height: 6px;
  min-width: 0;
  overflow: hidden;
  border-radius: 999px;
  background: var(--muted);
}

.job-progress-panel__bar-fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--job-progress-running);
  transition: width 240ms ease;
}

.job-progress-panel__item[data-status="completed"] .job-progress-panel__bar-fill {
  background: var(--job-progress-success);
}

.job-progress-panel__item[data-status="failed"] .job-progress-panel__bar-fill {
  background: var(--job-progress-danger);
}

.job-progress-panel__item[data-status="cancelled"] .job-progress-panel__bar-fill {
  background: color-mix(in srgb, var(--foreground) 35%, transparent);
}

.job-progress-panel__bar--indeterminate .job-progress-panel__bar-fill {
  animation: job-progress-panel-pulse 1.4s ease-in-out infinite;
}

@keyframes job-progress-panel-pulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .job-progress-panel__bar-fill {
    transition: none;
  }

  .job-progress-panel__bar--indeterminate .job-progress-panel__bar-fill {
    animation: none;
  }
}

.job-progress-panel__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
}

.job-progress-panel__meta > span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.job-progress-panel__error {
  margin-top: 2px;
  padding-top: 6px;
  border-top: 1px dashed var(--border);
}

.job-progress-panel__error-summary {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--job-progress-danger);
  cursor: pointer;
  list-style: none;
}

.job-progress-panel__error-summary::-webkit-details-marker {
  display: none;
}

.job-progress-panel__error-summary::before {
  content: "▸";
  flex: 0 0 auto;
  font-size: 10px;
}

.job-progress-panel__error[open] .job-progress-panel__error-summary::before {
  content: "▾";
}

.job-progress-panel__error-summary:hover {
  text-decoration: underline;
}

.job-progress-panel__error-summary:focus-visible {
  outline: 2px solid var(--ring, var(--border));
  outline-offset: 2px;
  border-radius: 4px;
}

.job-progress-panel__error-body {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 4px 8px;
  margin: 6px 0 0;
  font-size: 12px;
  line-height: 1.5;
}

.job-progress-panel__error-body dt {
  font-weight: 500;
  color: color-mix(in srgb, var(--foreground) 62%, transparent);
}

.job-progress-panel__error-body dd {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
}
"}]}

{"path":"/src/agent-ui/application/agent-events.ts","content":"import { z } from "zod";

/**
 * Project-owned business application events.
 *
 * Registered through `<Agent appEventSchemas={agentEventSchemas} />` and declared per
 * consumer Plugin in its manifest `data.events`. These are live notifications only:
 * they do not replay conversation history.
 */
const jobErrorSchema = z
  .object({
    code: z.string().optional(),
    message: z.string().optional(),
  })
  .loose();

export const jobProgressEventSchema = z
  .object({
    job_id: z.string().min(1),
    title: z.string().optional(),
    status: z.string().optional(),
    completed: z.number().optional(),
    total: z.number().optional(),
    error: jobErrorSchema.nullish(),
  })
  .loose();

export const agentEventSchemas = {
  "app.job.progress": jobProgressEventSchema,
};
"}

