+  overflow-wrap: anywhere;
+}
+
+.job-progress-panel__error {
+  margin-top: 2px;
+  padding-top: 6px;
+  border-top: 1px dashed var(--border);
+}
+
+.job-progress-panel__error-summary {
+  display: flex;
+  align-items: center;
+  gap: 4px;
+  font-size: 12px;
+  line-height: 1.5;
+  color: var(--job-progress-danger);
+  cursor: pointer;
+  list-style: none;
+}
+
+.job-progress-panel__error-summary::-webkit-details-marker {
+  display: none;
+}
+
+.job-progress-panel__error-summary::before {
+  content: "▸";
+  flex: 0 0 auto;
+  font-size: 10px;
+}
+
+.job-progress-panel__error[open] .job-progress-panel__error-summary::before {
+  content: "▾";
+}
+
+.job-progress-panel__error-summary:hover {
+  text-decoration: underline;
+}
+
+.job-progress-panel__error-summary:focus-visible {
+  outline: 2px solid var(--ring, var(--border));
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+.job-progress-panel__error-body {
+  display: grid;
+  grid-template-columns: auto minmax(0, 1fr);
+  gap: 4px 8px;
+  margin: 6px 0 0;
+  font-size: 12px;
+  line-height: 1.5;
+}
+
+.job-progress-panel__error-body dt {
+  font-weight: 500;
+  color: color-mix(in srgb, var(--foreground) 62%, transparent);
+}
+
+.job-progress-panel__error-body dd {
+  margin: 0;
+  min-width: 0;
+  overflow-wrap: anywhere;
+}
+

